		Command:       command,
		Workspace:     workspacePath,
		Status:        status,
		GeneratedAt:   timeNow(),
		Result:        result,
	}
	enc := json.NewEncoder(w)
	enc.SetIndent("", "  ")
	return enc.Encode(payload)
}

