	"testing"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/runcontrol"
)

type gauntletClock struct{ now time.Time }

func (c *gauntletClock) Now() time.Time { return c.now.UTC() }

// Proves: after compaction advances the replay boundary, `run follow --after 0`
// silently streams only the retained tail with no gap marker and exits 0.
func TestGauntletFollowSilentlyStreamsPartialJournalAfterCompaction(t *testing.T) {
	root := initializedWorkspace(t)
	ctx := context.Background()
	clock := &gauntletClock{now: time.Date(2026, 8, 1, 12, 0, 0, 123456789, time.UTC)}
	repository, err := runcontrol.OpenSQLite(ctx, root, runcontrol.SQLiteOptions{Clock: clock})
	if err != nil {
		t.Fatal(err)
	}
	snapshot, err := repository.Accept(ctx, runcontrol.Acceptance{Target: runcontrol.Target{Kind: "sprint", Operation: "execute", Project: "alpha", Sprint: "35"}})
	if err != nil {
		t.Fatal(err)
	}
	owner := runcontrol.Owner{ID: "gauntlet-owner", Process: runcontrol.ProcessIdentity{PID: 1}}
	attempt, _, err := repository.Claim(ctx, runcontrol.Claim{RunID: snapshot.RunID, Owner: owner, Lease: time.Hour})
	if err != nil {
		t.Fatal(err)
	}
	fence := runcontrol.Fence{RunID: snapshot.RunID, AttemptID: attempt.ID, OwnerID: owner.ID, FencingGeneration: attempt.FencingGeneration}
	for _, text := range []string{"early-1", "early-2", "early-3"} {
		if _, _, err := repository.Append(ctx, fence, runcontrol.EventDraft{Type: runcontrol.EventMessage, Payload: map[string]string{"message": text}}); err != nil {
			t.Fatal(err)
		}
	}
	if _, _, err := repository.ProposeTerminal(ctx, fence, runcontrol.TerminalProposal{Outcome: runcontrol.TerminalSucceeded, Reason: "completed", ProposedBy: "gauntlet"}); err != nil {
		t.Fatal(err)
	}
	clock.now = clock.now.Add(85 * time.Hour)
	report, err := repository.Compact(ctx, 64)
	if err != nil {
		t.Fatal(err)
	}
	if report.CompactedRuns != 1 {
		t.Fatalf("compaction did not compact the run: %+v", report)
	}
	if err := repository.Close(); err != nil {
		t.Fatal(err)
	}

	stdout, stderr, status := runForTest([]string{"--workspace", root, "run", "show", string(snapshot.RunID), "--json"})
	if status != ExitOK {
		t.Fatalf("show status=%d stderr=%q", status, stderr)
	}
	var envelope struct {
		Result struct {
			OldestRetainedSequence uint64 `json:"oldest_retained_sequence"`
			HistoryComplete        bool   `json:"history_complete"`
			LastSequence           uint64 `json:"last_sequence"`
		} `json:"result"`
	}
	if err := json.Unmarshal([]byte(stdout), &envelope); err != nil {
		t.Fatalf("show json: %v", err)
	}
	if envelope.Result.OldestRetainedSequence != 4 || envelope.Result.HistoryComplete || envelope.Result.LastSequence != 4 {
		t.Fatalf("expected compacted boundary oldest=4 last=4 history_complete=false, got %+v", envelope.Result)
	}

	followOut, followErr, followStatus := runForTest([]string{"--workspace", root, "run", "follow", string(snapshot.RunID), "--after", "0", "--json"})
	if followStatus != ExitOK || followErr != "" {
		t.Fatalf("follow status=%d stderr=%q", followStatus, followErr)
	}
	lines := nonEmptyLines(followOut)
	if len(lines) != 1 || !strings.Contains(lines[0], `"sequence":4`) {
		t.Fatalf("expected follow to emit only sequence 4 with no gap signal, got %q", followOut)
	}
}

func nonEmptyLines(s string) []string {
	var out []string
	for _, line := range strings.Split(strings.TrimSpace(s), "\n") {
		if strings.TrimSpace(line) != "" {
			out = append(out, line)
		}
	}
	return out
}
EOF
