package app

import (
	"context"
	"strings"
	"testing"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/runcontrol"
)

// Proves: `run follow --after <seq beyond LastSequence>` on a non-terminal run
// polls at 1 Hz indefinitely with zero output and no typed error (the web door
// returns cursor_ahead for the same request).
func TestGauntletFollowAheadOfLastSequencePollsSilently(t *testing.T) {
	root := initializedWorkspace(t)
	ctx := context.Background()
	repository, err := runcontrol.OpenSQLite(ctx, root, runcontrol.SQLiteOptions{})
	if err != nil {
		t.Fatal(err)
	}
	snapshot, err := repository.Accept(ctx, runcontrol.Acceptance{Target: runcontrol.Target{Kind: "runtime", Operation: "probe"}})
	if err != nil {
		t.Fatal(err)
	}
	if err := repository.Close(); err != nil {
		t.Fatal(err)
	}

	runCtx, cancel := context.WithTimeout(context.Background(), 1600*time.Millisecond)
	defer cancel()
	start := time.Now()
	var stdout, stderr strings.Builder
	status := Run(Config{
		Args: []string{"--workspace", root, "run", "follow", string(snapshot.RunID), "--after", "50"},
		Context: runCtx,
		Stdout: &stdout,
		Stderr: &stderr,
		Version: DefaultVersion(),
	})
	elapsed := time.Since(start)
	if status != ExitOK {
		t.Fatalf("expected clean observation-only exit 0, got %d stderr=%q", status, stderr.String())
	}
	if stdout.String() != "" {
		t.Fatalf("expected no output, got %q", stdout.String())
	}
	if elapsed < 1500*time.Millisecond {
		t.Fatalf("follow exited early after %v; expected it to keep polling", elapsed)
	}
}
EOF
