	if err != nil {
		t.Fatal(err)
	}
	if err := repository.Close(); err != nil {
		t.Fatal(err)
	}

	runCtx, cancel := context.WithTimeout(context.Background(), 1600*time.Millisecond)
	defer cancel()
	start := time.Now()
	var stdout, stderr strings.Builder
	status := Run(Config{
		Args: []string{"--workspace", root, "run", "follow", string(snapshot.RunID), "--after", "50"},
		Context: runCtx,
		Stdout: &stdout,
		Stderr: &stderr,
		Version: DefaultVersion(),
	})
	elapsed := time.Since(start)
	if status != ExitOK {
		t.Fatalf("expected clean observation-only exit 0, got %d stderr=%q", status, stderr.String())
	}
	if stdout.String() != "" {
		t.Fatalf("expected no output, got %q", stdout.String())
	}
	if elapsed < 1500*time.Millisecond {
		t.Fatalf("follow exited early after %v; expected it to keep polling", elapsed)
	}
}
